inspect_netcdf_ncdf4 <- function(path) { nc<-ncdf4::nc_open(path); on.exit(ncdf4::nc_close(nc),add=TRUE); att<-function(n,a,d=NULL){z<-tryCatch(ncdf4::ncatt_get(nc,n,a),error=function(e)list(hasatt=FALSE));if(isTRUE(z$hasatt))z$value else d}; dims<-lapply(nc$dim,function(d)list(name=d$name,length=d$len,values=d$vals,units=d$units)); vars<-lapply(nc$var,function(v)list(name=v$name,units=v$units,long_name=att(v$name,"long_name"),dimensions=vapply(v$dim,function(d)d$name,character(1)),dimension_lengths=vapply(v$dim,function(d)d$len,numeric(1)),data_signature=paste(vapply(v$dim,function(d)d$name,character(1)),collapse="|"),fill_value=v$missval,missing_value=att(v$name,"missing_value"),scale_factor=att(v$name,"scale_factor",1),add_offset=att(v$name,"add_offset",0))); names(vars)<-vapply(nc$var,function(v)v$name,character(1)); for(dn in setdiff(names(dims),names(vars))) vars[[dn]]<-list(name=dn,units=dims[[dn]]$units,dimensions=dn,dimension_lengths=dims[[dn]]$length,fill_value=NA_real_,missing_value=NA_real_,scale_factor=1,add_offset=0); tn<-intersect(c("valid_time","time"),names(dims));tn<-if(length(tn))tn[[1]]else NA_character_;ln<-intersect(c("longitude","lon"),names(dims));ln<-if(length(ln))ln[[1]]else NA_character_;an<-intersect(c("latitude","lat"),names(dims));an<-if(length(an))an[[1]]else NA_character_;tu<-if(!is.na(tn))dims[[tn]]$units else NA_character_;cal<-if(!is.na(tn))att(tn,"calendar")else NULL;if(!is.character(cal)||!length(cal)||is.na(cal)||!nzchar(cal))cal<-NULL;dec<-if(!is.na(tn))decode_netcdf_time(dims[[tn]]$values,tu,cal)else as.POSIXct(character());list(path=path,format=detect_download_format(path),variables=vars,dimensions=dims,coordinate_variables=list(longitude=if(!is.na(ln))dims[[ln]]$values else numeric(),latitude=if(!is.na(an))dims[[an]]$values else numeric()),time_variable=tn,time_units=tu,time_calendar_original=cal,time_calendar_effective=cal%||%"standard",decoded_dates=as.Date(dec,tz="UTC"),latitude_order=if(!is.na(an)&&length(dims[[an]]$values)>1)if(dims[[an]]$values[1]<tail(dims[[an]]$values,1))"ascending"else"descending"else"single",longitude_order=if(!is.na(ln)&&length(dims[[ln]]$values)>1)if(dims[[ln]]$values[1]<tail(dims[[ln]]$values,1))"ascending"else"descending"else"single") }
